(() => {
  // Freeze the reading clock to the same instant the fixtures (and the docs screenshot
  // pipeline's FIXED_CLOCK) are built around, so ages read as intended.
  const FIXED = Date.parse('2026-07-15T12:00:00Z');
  Date.now = () => FIXED;
  const btns = [...document.querySelectorAll('button')].map(b => b.textContent.trim());
  return JSON.stringify(btns);
})()

(async () => {
  [...document.querySelectorAll('button')].find(b => b.textContent.trim() === 'Refresh').click();
  await new Promise(r => setTimeout(r, 400));
  const dl = document.querySelectorAll('section dl')[4];
  return dl ? dl.innerText : 'no sweeps panel';
})()

